<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); $money=static fn($v)=>'R$ '.number_format((float)$v,2,',','.'); ?>
<section class="promotion-list"><h2>Promoções e cupons</h2><p><a href="/admin/promotion/create">+ Nova promoção</a></p>
<table><thead><tr><th>Promoção</th><th>Aplicação</th><th>Desconto</th><th>Websites</th><th>Validade</th><th>Status</th><th>Cupons</th><th>Usos</th><th></th></tr></thead><tbody>
<?php if (!$promotions): ?><tr><td colspan="9">Nenhuma promoção cadastrada.</td></tr><?php endif; ?>
<?php foreach($promotions as $p): ?><tr><td><?= $e($p['name']) ?><br><small>Prioridade <?= (int)$p['priority'] ?><?= $p['is_accumulative']?' · acumulativa':'' ?></small></td><td><?= $p['application_type']==='automatic'?'Automática':'Por cupom' ?></td><td><?= $p['discount_type']==='percent'?$e($p['discount_amount']).'%':$money($p['discount_amount']) ?></td><td><?= $e($p['websites']) ?></td><td><?= $e($p['starts_at'] ?: '—') ?> até <?= $e($p['ends_at'] ?: '—') ?></td><td><?= $p['is_active']?'Ativa':'Inativa' ?></td><td><?= (int)$p['coupon_count'] ?></td><td><?php if (\Iter\Admin\Auth::isAllowed('Iter_Promotion::usages')): ?><a href="/admin/promotion/uses?id=<?= (int)$p['promotion_id'] ?>"><?= (int)$p['redemption_count'] ?></a><?php else: ?><?= (int)$p['redemption_count'] ?><?php endif; ?></td><td><a href="/admin/promotion/edit?id=<?= (int)$p['promotion_id'] ?>">Editar</a> <form method="post" action="/admin/promotion/delete" style="display:inline" data-confirm="Remover esta promoção?"><?= \Iter\Core\FormKey::field() ?><input type="hidden" name="promotion_id" value="<?= (int)$p['promotion_id'] ?>"><button type="submit">Remover</button></form></td></tr><?php endforeach; ?>
</tbody></table></section>
